package com.bank.sequenced;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.SequencedCollection;
import java.util.logging.Logger;

// Wraps an ordered transaction list and exposes first/last/reversed uniformly.
class TransactionHistory {
    private static final Logger log = Logger.getLogger(TransactionHistory.class.getName());
    // ArrayList (a List) now implements SequencedCollection in Java 21.
    private final SequencedCollection<BigDecimal> txns = new ArrayList<>();

    void record(BigDecimal amount) { txns.addLast(amount); }   // append newest at the end

    BigDecimal mostRecent() { return txns.getLast(); }          // no more size()-1
    BigDecimal oldest()     { return txns.getFirst(); }

    // reversed() is a VIEW (no copy) → iterate newest-first for a statement.
    void printNewestFirst() {
        log.info(() -> "Newest-first: " + txns.reversed());
    }
}
