package com.bank.sequenced;

import java.time.LocalDateTime;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.SequencedMap;
import java.util.SequencedSet;
import java.util.logging.Logger;

// Ordered set + map gain first/last entry access uniformly in Java 21.
class RecentActivity {
    private static final Logger log = Logger.getLogger(RecentActivity.class.getName());
    private final SequencedSet<String> recentAccounts = new LinkedHashSet<>();
    private final SequencedMap<String, LocalDateTime> recentLogins = new LinkedHashMap<>();

    void touchAccount(String accountId) { recentAccounts.addLast(accountId); }
    void login(String accountId) { recentLogins.putLast(accountId, LocalDateTime.now()); }

    String firstTouched() { return recentAccounts.getFirst(); }
    String lastTouched()  { return recentAccounts.getLast(); }   // was awkward before 21

    void report() {
        log.info(() -> "first login entry = " + recentLogins.firstEntry());
        log.info(() -> "last login entry  = " + recentLogins.lastEntry());
        log.info(() -> "logins reversed    = " + recentLogins.reversed().keySet());
    }
}
