package com.bank.sequenced;

import java.math.BigDecimal;
import java.util.NoSuchElementException;
import java.util.logging.Logger;

public class SequencedDemo {
    private static final Logger log = Logger.getLogger(SequencedDemo.class.getName());

    public static void main(String[] args) {
        TransactionHistory history = new TransactionHistory();
        history.record(new BigDecimal("50000"));    // Rajesh → Priya
        history.record(new BigDecimal("25000"));
        history.record(new BigDecimal("10000"));
        log.info(() -> "oldest=Rs." + history.oldest() + " mostRecent=Rs." + history.mostRecent());
        history.printNewestFirst();

        RecentActivity activity = new RecentActivity();
        activity.touchAccount("SAV2001");            // Rajesh
        activity.touchAccount("CUR3001");            // Priya
        activity.login("SAV2001");
        activity.login("CUR3001");
        log.info(() -> "firstTouched=" + activity.firstTouched()
            + " lastTouched=" + activity.lastTouched());
        activity.report();

        // Contract: getFirst/getLast throw on an empty collection (fail fast).
        try {
            new TransactionHistory().mostRecent();
        } catch (NoSuchElementException e) {
            log.warning("empty history: getLast() correctly threw NoSuchElementException");
        }
    }
}
